package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen1Test {
    @Test
    public void testValueNull() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        JsonWriter jsonWriter2 = jsonWriter.value(null);
        assertEquals(jsonWriter2, jsonWriter.nullValue());
    }

    @Test
    public void testValueNonNull() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        JsonWriter jsonWriter2 = jsonWriter.value("test");
        jsonWriter2.flush();
        assertEquals("{\"test\":\"test\"}", jsonWriter2.toString());
    }

    @Test
    public void testValueZero() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        JsonWriter jsonWriter2 = jsonWriter.value(0);
        jsonWriter2.flush();
        assertEquals("{\"0\":0}", jsonWriter2.toString());
    }

    @Test
    public void testValuePositive() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        JsonWriter jsonWriter2 = jsonWriter.value(10);
        jsonWriter2.flush();
        assertEquals("{\"10\":10}", jsonWriter2.toString());
    }

    @Test
    public void testValueNegative() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        JsonWriter jsonWriter2 = jsonWriter.value(-10);
        jsonWriter2.flush();
        assertEquals("{\"-10\":-10}", jsonWriter2.toString());
    }

    @Test
    public void testValueRandom() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        Random random = new Random();
        JsonWriter jsonWriter2 = jsonWriter.value(random.nextInt());
        jsonWriter2.flush();
        JSON string = jsonWriter2.toString();
        JSON expected = "{\"" + random.nextInt() + "\":" + random.nextInt() + "}";
        assertEquals(expected, string);
    }

    @Test
    public void testValueNullLenient() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.setLenient(true);
        JsonWriter jsonWriter2 = jsonWriter.value(null);
        assertEquals(jsonWriter2, jsonWriter.nullValue());
    }
}
